for n in [23,24,26]:
 def dax(s):
  s=s.replace('Sales[Revenue]','Sales[NetRevenue]').replace('Sales[Amount]','Sales[NetRevenue]').replace('Sales[Cost]','Sales[TotalCost]').replace('COUNTROWS ( Sales )','DISTINCTCOUNT ( Sales[OrderID] )').replace('Sales[CustomerID]','Sales[CustomerKey]').replace('"Bikes"','"Electronics"').replace('Sales Bikes','Sales Electronics')
  if n==24:s=s.replace('ALL ( DimDate[Date] )','ALL ( DimDate )')
  return s
 edit(n,dax)
